import React, { Component } from 'react';
import { CButton, CInput } from '@coreui/react';
import { requestHeaderPOSTWithAuth } from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { Logger, reloadPage } from '../../Utils/Utils';
import { Loading } from '../Statuses/Statuses';
import { BACKEND_NEXUS_APP_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';
import { Table } from 'react-bootstrap';

const FILE_NAME = "ListPrograms.js";

class ListPrograms extends Component {

    constructor(props) {
        super(props);
        this.state = {
            isLoaded: false,
            programs: [],
            page: 1,
            size: 20,
            totalPages: 0,
            totalElements: 0,
            search: '',
            typeFilter: '',
        };
    }

    componentDidMount() {
        document.title = "Programs";
        this.fetchPrograms();
    }

    fetchPrograms = () => {
        const { page, size, search, typeFilter } = this.state;
        const userData = getUserDataFromLocalStorage();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/program/list';

        const reqData = {
            page,
            size,
            search: search.length >= 2 ? search : null,
            type: typeFilter || null,
        };

        fetch(API_URL, requestHeaderPOSTWithAuth(JSON.stringify(reqData), userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) { logoutProcedureForLocalStorage(); reloadPage(); }
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "fetchPrograms", "SUCCESS", "result", result);
            const pageData = result.data;
            this.setState({
                isLoaded: true,
                programs: pageData.content || [],
                totalPages: pageData.totalPages || 0,
                totalElements: pageData.totalElements || 0,
            });
        })
        .catch(error => {
            Logger(FILE_NAME, "fetchPrograms", "ERROR", "error", error);
            this.setState({ isLoaded: true });
        });
    }

    handleSearchSubmit = (e) => {
        e.preventDefault();
        this.setState({ page: 1 }, this.fetchPrograms);
    }

    goToPage = (newPage) => {
        this.setState({ page: newPage }, this.fetchPrograms);
    }

    render() {
        const { isLoaded, programs, page, totalPages, totalElements, search, typeFilter } = this.state;

        if (!isLoaded) return <Loading />;

        return (
            <div>
                <a href="#/program" style={{ textDecoration: 'none' }}>
                    <CButton color="secondary" className="mb-3">← Back to Program Home</CButton>
                </a>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
                    <h2>🏗️ Programs ({totalElements})</h2>
                    <div style={{ display: 'flex', gap: '8px' }}>
                        <CButton color="secondary" onClick={this.fetchPrograms} title="Refresh">🔄</CButton>
                        <a href="#/sub-program/create">
                            <CButton color="info">+ Create Sub-Program</CButton>
                        </a>
                        <a href="#/program/create">
                            <CButton color="success">+ Create Program</CButton>
                        </a>
                    </div>
                </div>

                {/* Search + Filter */}
                <form onSubmit={this.handleSearchSubmit} style={{ display: 'flex', gap: '8px', marginBottom: '16px', flexWrap: 'wrap' }}>
                    <CInput
                        placeholder="Search by name..."
                        value={search}
                        onChange={(e) => this.setState({ search: e.target.value })}
                        style={{ maxWidth: '250px' }}
                    />
                    <select
                        value={typeFilter}
                        onChange={(e) => this.setState({ typeFilter: e.target.value, page: 1 }, this.fetchPrograms)}
                        style={{ padding: '6px 12px', border: '1px solid #d8dbe0', borderRadius: '4px' }}
                    >
                        <option value="">All Types</option>
                        <option value="WORK">WORK</option>
                        <option value="PERSONAL">PERSONAL</option>
                    </select>
                    <CButton color="primary" type="submit">Search</CButton>
                    {(search || typeFilter) && (
                        <CButton color="secondary" onClick={() => this.setState({ search: '', typeFilter: '', page: 1 }, this.fetchPrograms)}>Clear</CButton>
                    )}
                </form>

                {/* Table */}
                <Table striped bordered hover style={{ width: '100%' }}>
                    <thead>
                        <tr>
                            <th>#</th>
                            <th>Name</th>
                            <th>Description</th>
                            <th>Type</th>
                            <th>Created (yyyy-mm-dd)</th>
                            <th>Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        {programs.length === 0 ? (
                            <tr><td colSpan="6" style={{ textAlign: 'center', color: '#888' }}>No programs found</td></tr>
                        ) : (
                            programs.map(prog => (
                                <tr key={'prog-' + prog.id}>
                                    <td>{prog.id}</td>
                                    <td><strong>{prog.name}</strong></td>
                                    <td style={{ color: '#666', maxWidth: '200px', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{prog.description || '—'}</td>
                                    <td>
                                        <span style={{
                                            padding: '2px 8px',
                                            borderRadius: '4px',
                                            fontSize: '12px',
                                            backgroundColor: prog.type === 'WORK' ? '#e3f2fd' : '#fce4ec',
                                            color: prog.type === 'WORK' ? '#1565c0' : '#c62828',
                                        }}>
                                            {prog.type}
                                        </span>
                                    </td>
                                    <td>{prog.createdOn ? new Date(prog.createdOn).toISOString().split('T')[0] : '—'}</td>
                                    <td>
                                        <CButton color="info" size="sm" onClick={() => window.open('#/program/' + prog.id, '_blank')}>
                                            View ↗
                                        </CButton>
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </Table>

                {/* Pagination */}
                {totalPages > 1 && (
                    <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '12px', marginTop: '16px' }}>
                        <CButton color="secondary" size="sm" disabled={page <= 1} onClick={() => this.goToPage(page - 1)}>← Prev</CButton>
                        <span>Page {page} of {totalPages}</span>
                        <CButton color="secondary" size="sm" disabled={page >= totalPages} onClick={() => this.goToPage(page + 1)}>Next →</CButton>
                    </div>
                )}
            </div>
        );
    }
}

export default ListPrograms;
